import numpy as np

def one_hot(labels, num_classes=-1):
    a = np.asarray(labels, dtype=np.int64)
    if num_classes == -1:
        num_classes = int(a.max()) + 1
    out = np.zeros(a.shape + (num_classes,), dtype=np.int64)
    np.put_along_axis(out, a[..., None], 1, axis=-1)
    return out.tolist()

