dl-activation-grads.solution:
import math
import numpy as np

def _sigmoid(z):
    out = np.empty_like(z)
    pos = z >= 0
    out[pos] = 1.0 / (1.0 + np.exp(-z[pos]))
    e = np.exp(z[~pos])
    out[~pos] = e / (1.0 + e)
    return out

def activation(name, z):
    z = np.asarray(z, dtype=float)
    s = _sigmoid(z)
    if name == "relu":
        f, d = np.maximum(z, 0.0), (z > 0).astype(float)
    elif name == "leaky_relu":
        f, d = np.where(z > 0, z, 0.01 * z), np.where(z > 0, 1.0, 0.01)
    elif name == "sigmoid":
        f, d = s, s * (1 - s)
    elif name == "tanh":
        t = np.tanh(z)
        f, d = t, 1 - t * t
    elif name == "softplus":
        f, d = np.logaddexp(0.0, z), s
    elif name == "silu":
        f, d = z * s, s * (1 + z * (1 - s))
    elif name == "gelu":
        cdf = 0.5 * (1 + np.array([math.erf(v / math.sqrt(2)) for v in z]))
        pdf = np.exp(-0.5 * np.minimum(z * z, 1e4)) / math.sqrt(2 * math.pi)
        f, d = z * cdf, cdf + z * pdf
    else:
        raise ValueError(name)
    return [f, d]

