dl-param-count.solution:
def count_params(input_shape, layers):
    shape = list(input_shape)
    total = 0
    for L in layers:
        t = L["type"]
        if t == "conv2d":
            c, h, w = shape
            k, s, p = L["k"], L.get("stride", 1), L.get("padding", 0)
            o = L["out"]
            total += o * c * k * k + (o if L.get("bias", True) else 0)
            shape = [o, (h + 2 * p - k) // s + 1, (w + 2 * p - k) // s + 1]
        elif t == "maxpool":
            c, h, w = shape
            k = L["k"]
            s = L.get("stride", k)
            shape = [c, (h - k) // s + 1, (w - k) // s + 1]
        elif t == "batchnorm":
            total += 2 * shape[0]
        elif t in ("relu", "dropout"):
            pass
        elif t == "flatten":
            n = 1
            for d in shape:
                n *= d
            shape = [n]
        elif t == "gap":
            shape = [shape[0]]
        elif t == "linear":
            f, o = shape[-1], L["out"]
            total += f * o + (o if L.get("bias", True) else 0)
            shape = shape[:-1] + [o]
        elif t == "embedding":
            total += L["num"] * L["dim"]
            shape = shape + [L["dim"]]
    return [total, shape]

