dl-early-stopping.solution:
def early_stopping(val_losses, patience, min_delta):
    best, best_epoch, bad = float("inf"), -1, 0
    for i, loss in enumerate(val_losses):
        if loss < best - min_delta:
            best, best_epoch, bad = loss, i, 0
        else:
            bad += 1
            if bad >= patience:
                return [i, best_epoch]
    return [len(val_losses) - 1, best_epoch]

dl-precision-recall-f1.solution:
def prf_at_threshold(labels, probs, threshold):
    tp = fp = fn = tn = 0
    for y, p in zip(labels, probs):
        flag = p >= threshold
        if flag and y == 1:
            tp += 1
        elif flag:
            fp += 1
        elif y == 1:
            fn += 1
        else:
            tn += 1
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return [precision, recall, f1, [tp, fp, fn, tn]]

