import numpy as np

def augment(volume, flips, shift):
    a = np.array(volume)
    for axis in flips:
        a = np.flip(a, axis=axis)
    out = np.zeros_like(a)
    src, dst = [], []
    for n, s in zip(a.shape, shift):
        if abs(s) >= n:
            return out.tolist()
        if s >= 0:
            src.append(slice(0, n - s)); dst.append(slice(s, n))
        else:
            src.append(slice(-s, n)); dst.append(slice(0, n + s))
    out[tuple(dst)] = a[tuple(src)]
    return out.tolist()

dl-connected-components.solution:
from collections import deque

def components(grid, connectivity):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    steps = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    if connectivity == 8:
        steps += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
    seen = [[False] * cols for _ in range(rows)]
    out = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] and not seen[r][c]:
                seen[r][c] = True
                queue, cells = deque([(r, c)]), []
                while queue:
                    y, x = queue.popleft()
                    cells.append((y, x))
                    for dy, dx in steps:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx] = True
                            queue.append((ny, nx))
                n = len(cells)
                out.append([n, sum(y for y, _ in cells) / n, sum(x for _, x in cells) / n])
    out.sort(key=lambda t: (-t[0], t[1], t[2]))
    return out

